// === Tab: mySketch ===
/**
 * Rhodium Clouds — OpenProcessing.org (p5.js WEBGL)
 * Original by unknown author (CC BY-NC-SA 3.0, Shadertoy default)
 * https://www.shadertoy.com/view/XXyGzh
 * Cross-translation by Novvera Ltd
 * GLSL ES 3.00
 *
 * stanh(vec2) from Common pass included inline.
 * No textures. iTime only.
 */

const VERT = `#version 300 es
precision highp float;
in  vec3 aPosition;
void main() {
  vec4 pos    = vec4(aPosition, 1.0);
  pos.xy      = pos.xy * 2.0 - 1.0;
  gl_Position = pos;
}`;

const FRAG = `#version 300 es
precision highp float;
uniform float uTime;
uniform vec2  uResolution;
out vec4 fragColor;

// from Common pass
vec2 stanh(vec2 a) {
  return tanh(clamp(a, -40., 40.));
}

void main() {
  vec2 v = uResolution;
  vec2 u = .2*(gl_FragCoord.xy + gl_FragCoord.xy - v) / v.y;

  vec4 z = vec4(1,2,3,0);
  vec4 o = vec4(1,2,3,0);

  for (float a = .5, t = uTime, i = 0.;
       ++i < 19.;
       o += (1. + cos(z + t))
          / length((1. + i*dot(v,v))
                 * sin(1.5*u/(.5 - dot(u,u)) - 9.*u.yx + t))
      )
  {
    v = cos(++t - 7.*u*pow(a += .03, i)) - 5.*u;
    u += stanh(40. * dot(u *= mat2(cos(i + .02*t - z.wxzw*11.)), u)
                   * cos(1e2*u.yx + t)) / 2e2
       + .2 * a * u
       + cos(4./exp(dot(o,o)/1e2) + t) / 3e2;
  }

  fragColor = 25.6 / (min(o, 13.) + 164. / o)
            - dot(u,u) / 250.;
  fragColor.a = 1.0; // force opaque — p5.js WEBGL composites against white bg using alpha
}`;

let rc;

function setup() {
  createCanvas(1920, 1080, WEBGL);
  pixelDensity(2);
  noStroke();
  rc = createShader(VERT, FRAG);
}

function draw() {
  shader(rc);
  rc.setUniform('uTime', millis()/1000.0);
  rc.setUniform('uResolution', [width*2, height*2]);
  rect(0, 0, width, height);
}

function windowResized() { resizeCanvas(width, height); }

function mouseClicked(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

